(()=>{'use strict';
const URLS={pyramid:['/api/public/structural-power/pyramid','/data/behind-the-curtain-pyramid.json'],people:['/api/public/structural-power/people','/data/behind-the-curtain-people-registry.json'],core:['/api/public/structural-power/core','/data/behind-the-curtain.json'],families:['/api/public/structural-power/families','/data/behind-the-curtain-family-access.json'],history:['/api/public/structural-power/history','/data/behind-the-curtain-living-access-history.json'],continuity:['/api/public/structural-power/continuity','/data/behind-the-curtain-continuity-layers.json']};
const MODE_RANK={proof:0,structural:1,symbolic:2};
const state={mode:'structural',selectedLevel:'public-stage',models:null,lastLoaded:null,timer:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const array=v=>Array.isArray(v)?v:[];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const slug=v=>String(v||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const label=v=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const clamp=v=>Math.max(0,Math.min(100,Number(v)||0));
const list=v=>array(v).length?`<ul>${array(v).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="muted">No current record.</p>';
const classification=v=>`<span class="classification ${esc(v||'unsupported')}">${esc(label(v||'unsupported'))}</span>`;
const refKey=ref=>`${ref.dataset}:${ref.id}`;
async function load(urls){let lastError;for(const url of array(urls)){try{const r=await fetch(`${url}?v=${Date.now()}`,{cache:'no-store',headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`${url}: HTTP ${r.status}`);const type=String(r.headers.get('content-type')||'').toLowerCase();if(!type.includes('application/json'))throw new Error(`${url}: non-JSON response`);return await r.json()}catch(error){lastError=error}}throw lastError||new Error('Evidence package unavailable')}
function buildIndexes(models){const historical=array(models.families.historicalArchitects).map(x=>({...x,id:slug(x.name),_dataset:'historical'}));return{people:new Map(array(models.people.people).map(x=>[x.id,{...x,_dataset:'people'}])),family:new Map(array(models.families.families).map(x=>[x.id,{...x,_dataset:'family'}])),core:new Map(array(models.core.powerCenters).map(x=>[x.id,{...x,_dataset:'core'}])),historical:new Map(historical.map(x=>[x.id,x])),symbolic:new Map(array(models.pyramid.symbolicDossiers).map(x=>[x.id,{...x,_dataset:'symbolic'}]))}}
function resolve(ref){return ref&&state.models?.indexes?.[ref.dataset]?.get(ref.id)||null}
function displayName(e){return e?.name||e?.title||'Unresolved entity'}
function entityClass(e){return e?.classification||'unsupported'}
function sourceIndex(){const all=[...array(state.models.people.sources),...array(state.models.core.sources),...array(state.models.families.sources)];return new Map(all.map(x=>[x.id,x]))}
function sourcesFor(e){const idx=sourceIndex();return array(e?.sourceIds).map(id=>idx.get(id)).filter(Boolean)}
function sourceBlock(e){const items=sourcesFor(e);if(!items.length)return'<p class="muted">No directly resolved source record in this package.</p>';return items.map(s=>`<article class="source-card"><strong>${esc(s.publisher)}</strong><h4>${esc(s.title)}</h4><p><b>Establishes:</b> ${esc(s.establishes)}</p><p><b>Does not establish:</b> ${esc(s.doesNotEstablish)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source record</a></article>`).join('')}
function modeAllows(level){return MODE_RANK[state.mode]>=MODE_RANK[level.minimumMode||'proof']}
function humanApex(){return [...array(state.models.people.people)].sort((a,b)=>b.crossSystemScore-a.crossSystemScore||a.name.localeCompare(b.name)).slice(0,10)}
function memberRefsForLevel(level){if(level.memberQuery==='cross-system-top-10')return humanApex().map(x=>({dataset:'people',id:x.id}));return array(level.memberRefs)}
function tierAccess(person,tierId){return array(person?.tierAccess).find(x=>x.tierId===tierId)||null}
function memberButtons(refs){return array(refs).map(ref=>{const e=resolve(ref);return e?`<button class="entity-chip${e._dataset==='symbolic'?' symbolic':''}" type="button" data-entity="${esc(refKey(ref))}">${esc(displayName(e))}</button>`:`<span class="entity-chip muted">Identity unresolved: ${esc(ref.id)}</span>`}).join('')}
function renderPyramid(){const target=$('#pyramid-levels');if(!target)return;const levels=[...array(state.models.pyramid.levels)].sort((a,b)=>b.level-a.level);target.innerHTML=levels.map(level=>{const width=28+(12-level.level)*6.18,count=memberRefsForLevel(level).filter(resolve).length,classes=['pyramid-level',level.id===state.selectedLevel?'active':'',level.minimumMode==='symbolic'?'symbolic':'',level.classification==='disputed'?'disputed':'',modeAllows(level)?'':'hidden-mode'].filter(Boolean).join(' ');return`<button class="${classes}" type="button" data-level="${esc(level.id)}" style="--tier-width:${width}%"><span class="pyramid-line"><span class="pyramid-number">${level.level}</span><span class="pyramid-copy"><strong>${esc(level.name)}</strong><small>${esc(level.kicker)}</small></span><span class="pyramid-count">${count} named</span></span></button>`}).join('');let selected=levels.find(x=>x.id===state.selectedLevel&&modeAllows(x));if(!selected)selected=levels.filter(modeAllows).sort((a,b)=>a.level-b.level)[0];if(selected){state.selectedLevel=selected.id;renderLevelDetail(selected);renderSelectedTier(selected)}}
function renderLevelDetail(level){const refs=memberRefsForLevel(level);const target=$('#pyr-detail');if(!target)return;target.innerHTML=`<span class="level-mark">LEVEL ${level.level} · ${esc(level.kicker)}</span><h3>${esc(level.name)}</h3>${classification(level.classification)}<p><strong>${esc(level.question)}</strong></p><p>${esc(level.thesis)}</p><div class="pyr-detail-members">${memberButtons(refs)}</div><details open><summary>Mechanisms of access</summary>${list(level.mechanisms)}</details><div class="pyr-boundary"><strong>COUNTERWEIGHT</strong><p>${esc(level.counterweight)}</p></div>`}
function personTierCard(person,level){const access=tierAccess(person,level.id);const score=level.id==='human-apex'?person.crossSystemScore:access?.score;const basis=access?.basis||array(person.accessToPower)[0]||'Current documented role.';const mechanism=access?.mechanism||'Cross-system breadth calculated from independent tier scores.';return`<article class="apex-person"><span class="apex-rank">${score!=null?Math.round(score):'—'}</span><div><h3><button class="entity-chip" type="button" data-entity="people:${esc(person.id)}">${esc(person.name)}</button></h3><p><strong>${esc(person.currentRole)}</strong></p><p>${esc(person.organization)}</p><p><b>Mechanism:</b> ${esc(mechanism)}</p><p>${esc(basis)}</p>${classification(access?.classification||person.classification)}<p class="muted"><b>Boundary:</b> ${esc(person.notEstablished)}</p></div><span class="apex-score">${score!=null?Number(score).toFixed(1):'—'}</span></article>`}
function genericCard(e,ref){if(e._dataset==='family')return`<article class="pyr-card"><span class="eyeline">${esc(e.type||'Dynastic structure')}</span><h3><button class="entity-chip" data-entity="${esc(refKey(ref))}" type="button">${esc(e.name)}</button></h3><p><strong>Access score:</strong> ${esc(e.accessScore)}/100</p><p>${esc(array(e.documentedAccess)[0]||'Evidence summary unavailable.')}</p><div class="pyr-boundary"><strong>NOT ESTABLISHED</strong><p>${esc(e.unsupportedClaim)}</p></div></article>`;if(e._dataset==='core')return`<article class="pyr-card"><span class="eyeline">Structural system</span><h3><button class="entity-chip" data-entity="${esc(refKey(ref))}" type="button">${esc(e.name)}</button></h3><p>${esc(array(e.strongestEvidence)[0]||array(e.mechanisms)[0]||'Institutional evidence record.')}</p><p><b>Counterargument:</b> ${esc(e.strongestCounterargument||'Authority remains distributed and constrained.')}</p></article>`;if(e._dataset==='historical')return`<article class="pyr-card"><span class="eyeline">Historical continuity review</span><h3><button class="entity-chip" data-entity="${esc(refKey(ref))}" type="button">${esc(e.name)}</button></h3><p>${esc(e.summary||e.documentedRole||'Historical influence under evidence review.')}</p></article>`;return`<article class="symbolic-card">${classification(e.classification)}<h3><button class="entity-chip symbolic" data-entity="${esc(refKey(ref))}" type="button">${esc(e.name)}</button></h3><p>${esc(e.summary)}</p><p><strong>Not established:</strong> ${esc(e.notEstablished)}</p></article>`}
function renderSelectedTier(level){const section=$('#names'),target=$('#human-apex-grid');if(!section||!target)return;const h=section.querySelector('h2'),p=section.querySelector('.pyr-section-head p'),eye=section.querySelector('.eyebrow');if(eye)eye.textContent=`LEVEL ${level.level} · SELECTED ROSTER`;if(h)h.textContent=level.id==='human-apex'?'THE CROSS-SYSTEM HUMAN APEX.':level.name.toUpperCase()+'.';if(p)p.textContent=level.id==='human-apex'?'Only Level 11 displays the calculated cross-system Top 10. Every lower tier uses its own independent roster and score.':`This roster is specific to ${level.name}. Names appear here only through the mechanism defined for this tier.`;const refs=memberRefsForLevel(level);target.className=refs.some(r=>r.dataset!=='people')?'pyr-grid':'apex-grid';const cards=refs.map(ref=>{const e=resolve(ref);if(!e)return'';return e._dataset==='people'?personTierCard(e,level):genericCard(e,ref)}).join('');target.innerHTML=cards||'<article class="pyr-fail"><h3>No verified roster available</h3><p>This tier fails closed until its independent evidence contract is satisfied.</p></article>'}
function renderChokepoints(){const t=$('#choke-grid');if(!t)return;t.innerHTML=array(state.models.pyramid.chokePoints).map((x,i)=>`<article class="choke-card"><span class="choke-num">${String(i+1).padStart(2,'0')}</span><h3>${esc(x.name)}</h3><p><strong>${esc(x.question)}</strong></p><div class="pyr-detail-members">${memberButtons(x.memberRefs)}</div></article>`).join('')}
function stepHtml(step){if(step.label)return`<span class="path-node">${esc(step.label)}</span>`;const e=resolve(step);return e?`<button class="path-node entity-chip" type="button" data-entity="${esc(refKey(step))}">${esc(displayName(e))}</button>`:`<span class="path-node muted">Unresolved: ${esc(step.id)}</span>`}
function renderPathways(){const t=$('#pathway-grid');if(!t)return;const paths=array(state.models.pyramid.pathways).filter(x=>state.mode==='symbolic'||x.classification!=='symbolic_or_mythological');t.innerHTML=paths.map(x=>`<article class="pyr-card"><span class="eyeline">${esc(label(x.classification))}</span><h3>${esc(x.title)}</h3><div class="pathway">${array(x.steps).map((s,i)=>`<span class="path-step">${i?'<span class="path-arrow">→</span>':''}${stepHtml(s)}</span>`).join('')}</div><div class="pyr-boundary"><strong>BOUNDARY</strong><p>${esc(x.boundary)}</p></div></article>`).join('')}
function renderDynasties(){const t=$('#dynasty-grid');if(!t)return;t.innerHTML=[...array(state.models.families.families)].sort((a,b)=>a.rank-b.rank).map(f=>genericCard({...f,_dataset:'family'},{dataset:'family',id:f.id})).join('')}
function hypothesisCard(h){return`<article class="pyr-card">${classification(h.classification)}<h3>${esc(h.name)}</h3><p>${esc(h.thesis)}</p><details><summary>Evidence that supports investigation</summary>${list(h.evidenceFor)}</details><details><summary>Evidence and limits against the claim</summary>${list(h.evidenceAgainst)}</details><p><b>Required to establish:</b> ${esc(h.requiredEvidence)}</p><div class="pyr-boundary"><strong>NOT ESTABLISHED</strong><p>${esc(h.notEstablished)}</p></div></article>`}
function renderCouncils(){const t=$('#council-grid');if(!t)return;const review=state.models.pyramid.innerCouncilsReview;const bodies=array(review.namedBodies).map(name=>`<article class="pyr-card"><span class="eyeline">Named decision body</span><h3>${esc(name)}</h3><p>Inspect its mandate, membership, funding, decision rights, implementation record and vetoes before inferring wider coordination.</p></article>`).join('');const hypotheses=array(state.models.pyramid.hiddenHandHypotheses).filter(h=>state.mode!=='proof'||['documented_fact','strongly_supported_assessment'].includes(h.classification)).filter(h=>state.mode==='symbolic'||h.classification!=='speculative_hypothesis').map(hypothesisCard).join('');t.innerHTML=`<article class="pyr-card"><span class="eyeline">${esc(label(review.status))}</span><h3>Current finding</h3><p>${esc(review.currentFinding)}</p></article>${hypotheses}${bodies}`}
function renderSymbolic(){const t=$('#symbolic-grid');if(!t)return;const section=t.closest('.pyr-section');if(section)section.style.display=state.mode==='symbolic'?'':'none';t.innerHTML=state.mode==='symbolic'?array(state.models.pyramid.symbolicDossiers).map(x=>genericCard({...x,_dataset:'symbolic'},{dataset:'symbolic',id:x.id})).join(''):''}
function renderFreshness(){const t=$('#freshness-grid');if(!t)return;const dates=[state.models.pyramid.asOf,state.models.people.asOf,state.models.core.asOf,state.models.families.asOf].filter(Boolean).sort(),latest=dates.at(-1)||'Unknown',next=array(state.models.people.people).map(x=>x.nextReviewDue).filter(Boolean).sort()[0]||'Not scheduled',poll=state.models.pyramid.updatePolicy?.pollMinutes||15,snapshots=array(state.models.history.snapshots).length;t.innerHTML=`<article class="fresh-card"><span class="fresh-dot"></span><strong>${esc(latest)}</strong><span>latest model date</span></article><article class="fresh-card"><strong>${esc(next)}</strong><span>next role review</span></article><article class="fresh-card"><strong>${snapshots}</strong><span>preserved snapshots</span></article><article class="fresh-card"><strong>${poll} min</strong><span>browser evidence refresh</span></article>`}
function renderSources(){const t=$('#source-grid');if(!t)return;const unique=[...new Map([...sourceIndex().values()].map(x=>[x.url,x])).values()];t.innerHTML=unique.map(s=>`<article class="source-card"><span class="eyeline">${esc(s.publisher)}</span><h3>${esc(s.title)}</h3><p><strong>Establishes:</strong> ${esc(s.establishes)}</p><p><strong>Does not establish:</strong> ${esc(s.doesNotEstablish)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source record</a><small>${esc(s.date||'Reviewed source')}</small></article>`).join('')}
function renderStats(){const levelRefs=array(state.models.pyramid.levels).flatMap(memberRefsForLevel),chokeRefs=array(state.models.pyramid.chokePoints).flatMap(x=>array(x.memberRefs)),unique=new Set([...levelRefs,...chokeRefs].map(refKey));$('#pyr-level-count').textContent=state.models.pyramid.levels.length;$('#pyr-name-count').textContent=unique.size;$('#pyr-source-count').textContent=sourceIndex().size;$('#pyr-evidence-date').textContent=[state.models.pyramid.asOf,state.models.people.asOf,state.models.core.asOf,state.models.families.asOf].filter(Boolean).sort().at(-1)||'Unknown';$('#pyr-boundary').textContent=`${state.models.pyramid.editorialBoundary} ${state.models.people.editorialBoundary} ${state.models.families.editorialBoundary}`}
function profileBlocks(e){if(e._dataset==='people')return`<div class="profile-block"><h4>Current verified role</h4><p>${esc(e.currentRole)}</p><p>${esc(e.organization)}</p><p class="muted">Verified ${esc(e.verifiedAt)} · review due ${esc(e.nextReviewDue)}</p></div><div class="profile-block"><h4>Tier-specific access</h4>${array(e.tierAccess).map(a=>`<p><strong>${esc(label(a.tierId))} · ${esc(a.score)}/100</strong><br>${esc(a.mechanism)}<br>${esc(a.basis)}</p>`).join('')}</div><div class="profile-block"><h4>Access to people and systems</h4>${list(e.accessToPower)}</div><div class="profile-block"><h4>Constraints</h4>${list(e.constraints)}</div><div class="profile-block"><h4>What is not established</h4><p>${esc(e.notEstablished)}</p></div>`;if(e._dataset==='family')return`<div class="profile-block"><h4>Documented access</h4>${list(e.documentedAccess)}</div><div class="profile-block"><h4>Structures reached</h4>${list(e.structuresReached)}</div><div class="profile-block"><h4>Constraints</h4>${list(e.constraints)}</div><div class="profile-block"><h4>Unsupported claim boundary</h4><p>${esc(e.unsupportedClaim)}</p></div>`;if(e._dataset==='core')return`<div class="profile-block"><h4>Mechanisms</h4>${list(e.mechanisms)}</div><div class="profile-block"><h4>Strongest evidence</h4>${list(e.strongestEvidence)}</div><div class="profile-block"><h4>Counterargument</h4><p>${esc(e.strongestCounterargument)}</p></div>`;return`<div class="profile-block"><h4>Interpretive dossier</h4><p>${esc(e.summary||e.documentedRole||'Historical or symbolic record.')}</p>${list(e.interpretations)}</div><div class="profile-block"><h4>Not established</h4><p>${esc(e.notEstablished||'This record does not establish a modern command chain.')}</p></div>`}
function openProfile(key){const [dataset,id]=String(key).split(':');const e=resolve({dataset,id});if(!e)return;const score=e._dataset==='people'?e.crossSystemScore:e.accessScore??e.structuralPowerScore;$('#pyr-modal-content').innerHTML=`<span class="eyeline">${esc(label(e._dataset))}</span><h2 id="pyr-modal-title">${esc(displayName(e))}</h2>${classification(entityClass(e))}${score!=null?`<div class="profile-score">${Number(score).toFixed(1)}</div>`:''}<div class="profile-grid">${profileBlocks(e)}</div><section><h3>Source boundaries</h3><div class="source-grid">${sourceBlock(e)}</div></section>`;$('#pyr-modal').classList.add('open');document.body.style.overflow='hidden'}
function closeProfile(){$('#pyr-modal')?.classList.remove('open');document.body.style.overflow=''}
function renderAll(){renderStats();renderPyramid();renderChokepoints();renderPathways();renderDynasties();renderCouncils();renderSymbolic();renderFreshness();renderSources();$$('[data-view-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.viewMode===state.mode)))}
function toast(msg){const t=$('#pyr-toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2400)}
async function refresh({silent=false}={}){const rs=$('#pyr-refresh-state');if(rs)rs.textContent='SYNC';try{const [pyramid,people,core,families,history,continuity]=await Promise.all(Object.values(URLS).map(load));const models={pyramid,people,core,families,history,continuity};models.indexes=buildIndexes(models);state.models=models;state.lastLoaded=new Date();renderAll();if(rs)rs.textContent='LIVE';if(!silent)toast('Independent tier evidence refreshed.');clearInterval(state.timer);state.timer=setInterval(()=>refresh({silent:true}),Math.max(5,Number(pyramid.updatePolicy?.pollMinutes)||15)*60000)}catch(error){console.error(error);if(rs)rs.textContent='CLOSED';const p=$('#pyramid-levels');if(p)p.innerHTML='<article class="pyr-fail"><h3>The Pyramid has failed closed.</h3><p>A required tier registry or evidence package could not be loaded. No names or conclusions are invented.</p></article>';const d=$('#pyr-detail');if(d)d.innerHTML='<span class="level-mark">EVIDENCE PACKAGE ERROR</span><h3>Display suspended.</h3><p>Repair and rebuild the source packages.</p>';if(!silent)toast('Evidence refresh failed closed.')}}
function bind(){document.addEventListener('click',event=>{const level=event.target.closest('[data-level]');if(level){state.selectedLevel=level.dataset.level;renderPyramid();document.querySelector('#names')?.scrollIntoView({behavior:'smooth',block:'start'});return}const entity=event.target.closest('[data-entity]');if(entity){openProfile(entity.dataset.entity);return}const mode=event.target.closest('[data-view-mode]');if(mode){state.mode=mode.dataset.viewMode;renderAll();toast(`${mode.textContent.trim()} activated.`)}});$('#pyr-refresh')?.addEventListener('click',()=>refresh());$('#pyr-modal-close')?.addEventListener('click',closeProfile);$('#pyr-modal')?.addEventListener('click',e=>{if(e.target.id==='pyr-modal')closeProfile()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.lastLoaded&&Date.now()-state.lastLoaded.getTime()>15*60000)refresh({silent:true})})}
function init(){bind();refresh()}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
